// Suggested workflows, not extracted university requirements. Keep instructions editable.
const library={label:'University of Nottingham Library',url:'https://www.nottingham.ac.uk/library/'};
const scholar={label:'Find academic sources · Google Scholar',url:'https://scholar.google.com/'};
const writing={label:'Writing process · Purdue OWL',url:'https://owl.purdue.edu/owl/general_writing/the_writing_process/index.html'};
const citing={label:'Referencing guidance · Purdue OWL',url:'https://owl.purdue.edu/owl/research_and_citation/index.html'};
const python={label:'Python tutorial (if your course uses Python)',url:'https://docs.python.org/3/tutorial/'};
const s=(text,detail,links=[])=>({text,detail,links});
const moodle={label:'Open Moodle for your assessment brief',url:'https://moodle.nottingham.ac.uk/my/courses.php'};
const read=s('Read the brief and marking criteria','Open the assessment brief. Write down the question, required deliverables, word limit or format, marking criteria and submission instructions. Check any extension against the deadline in this app.',[moodle]);
const submit=s('Check the final file and submit','Compare your work with every requirement in the brief. Check the file type and filename, upload it to the correct submission page, reopen the upload and save the receipt. Mark the assignment completed after submission.',[moodle]);
const templates={
 essay:[read,s('Find evidence and make a source list','Identify the key terms in the question. Search your reading list and library, select relevant academic sources, and record page numbers and citation details as you read.',[library,scholar]),s('Build an argument and outline','Write your answer to the question in one sentence. Plan an introduction, a sequence of evidence-backed arguments and a conclusion. Assign an approximate word budget to each section.',[writing]),s('Write the first draft','Draft one section at a time. Explain the claim, support it with evidence, and show how it answers the question. Keep track of citations while writing.',[writing]),s('Revise, reference and proofread','Check the argument against the marking criteria. Improve paragraph order, remove repetition, confirm the word count and check that in-text citations match the reference list. Use the referencing style named in your brief.',[citing]),submit],
 report:[read,s('Plan the report structure','Use the sections required by the brief. Decide what each section must explain, which results or evidence it needs, and what belongs in an appendix.',[writing]),s('Gather and analyse the evidence','Collect the required sources or data. Record your method, units, assumptions and limitations. Prepare clearly labelled tables or figures where they help answer the question.',[library,scholar]),s('Write the report sections','Describe the method and findings clearly, then explain what the results mean. Connect conclusions to evidence and include recommendations only if the brief asks for them.',[writing]),s('Check results, citations and presentation','Recheck calculations, units and figure labels. Confirm that the discussion matches the results, acknowledge limitations, and check the required referencing and formatting.',[citing]),submit],
 problem:[read,s('List the questions and relevant methods','Break the problem set into separate questions. Match each with the relevant lecture, definition, formula or method. Write down any constraints and what each question asks you to find.'),s('Work through each solution','Attempt each question before checking examples. Show the important working, label variables and units, and note where a result depends on an assumption.'),s('Check and explain your answers','Check calculations independently where possible. Test whether the answer has the right units and a sensible size. Add a short explanation of the method, not just the final answer.'),submit],
 coding:[read,s('Turn the brief into a build checklist','List the required inputs, outputs, behaviour and constraints. Sketch a small solution and identify how you will verify each requirement. Use the language and libraries permitted by the module.'),s('Implement the smallest working version','Build the core behaviour first, in small pieces. Run it after each change. Keep a record of decisions and any sources you use.',[python]),s('Test normal, edge and invalid inputs','Run meaningful examples including empty inputs, boundary values and error cases. Compare results with the brief and fix the underlying problems.'),s('Prepare documentation and submission files','Explain setup, how to run the program, key decisions and known limitations. Check that it runs from a clean folder using only the submitted files. Remove secrets and unnecessary generated files.'),submit],
 presentation:[read,s('Choose the message and slide outline','Write the main point the audience should remember. Plan a clear opening, a short sequence of supporting points and a conclusion. Match the structure to the allotted time.'),s('Gather evidence and build the slides','Use the reading list and reliable sources to support the message. Keep slides readable, label visuals and record references. Follow any slide or accessibility requirements.',[library,scholar]),s('Rehearse aloud and time the presentation','Deliver the whole presentation with a timer. Simplify any section that runs long, practise transitions, and prepare answers to likely questions.'),s('Check delivery and submit required materials','Check the room or recording instructions, audio and file compatibility. Prepare a backup and submit slides or recordings if required. Mark completed when all assessed parts are finished.')],
 exam:[read,s('Map the examinable topics','Use the module guidance to list topics, assessment format and permitted materials. Mark weak areas and identify the relevant lectures or chapters.'),s('Recall and practise without notes','Answer practice questions or explain each concept from memory. Check against course materials afterward and keep an error list.'),s('Attempt timed questions','Use approved past papers or practice questions under the stated conditions. Review where marks were lost and revisit those methods or concepts.'),s('Review weak areas and check exam arrangements','Repeat the questions you struggled with. Confirm the exam time, location or online instructions and permitted materials. Mark completed after the exam.')],
 other:[read,s('Break the deliverables into smaller pieces','Turn each required output in the brief into a concrete item. Decide what finished work should look like and which materials you need.',[library]),s('Produce a first complete version','Work through the deliverables one at a time, keeping the marking criteria visible. Record sources or methods where the brief requires them.'),s('Review against the marking criteria','Check that every requested part is present and accurate. Improve unclear sections and check the required format and references.',[citing]),submit]
};
export function generatedSteps(task){return (templates[task.type]||templates.other).map((step,i)=>({...step,id:`guide:${task.type||'other'}:${i}`,done:false,links:step.links.map(l=>({...l}))}));}
export function stepsFor(task){return task.steps?.length?task.steps:generatedSteps(task);}
function matchingStep(task,step){const list=templates[task.type]||templates.other;const exact=list.find(s=>s.text===step.text);if(exact)return exact;const text=step.text.toLowerCase();if(/brief|criteria|requirements/.test(text))return read;if(/submit|upload|receipt/.test(text))return submit;if(/proof|revise|reference|citation|review/.test(text))return list.find(s=>/revise|check results|review against|check and explain|review weak/i.test(s.text))||list.at(-2);if(/research|source|evidence|reading|analys|dataset/.test(text))return list.find(s=>/find evidence|gather|analyse/i.test(s.text))||s(step.text,'Use the sources or dataset required by your brief. Record your method, evidence and limitations so you can explain the result.',[library,scholar]);if(/write|draft|report/.test(text))return list.find(s=>/first draft|report sections|first complete/i.test(s.text))||s(step.text,'Draft the required sections using your outline and the marking criteria. Support claims with appropriate evidence and keep track of citations.',[writing]);if(/test|debug/.test(text))return templates.coding[3];return null;}
export function stepDetail(task,step){if(step.detail)return step.detail;return matchingStep(task,step)?.detail||`Complete “${step.text}” using your assessment brief and the requirements below. Check the result against the marking criteria before ticking this step.`;}
export function resourcesFor(task,step=null){const stepLinks=step?.links?.length?step.links:step?matchingStep(task,step)?.links||[library]:[];const search={label:'Search academic sources for this assignment',url:'https://scholar.google.com/scholar?q='+encodeURIComponent(task.title+' '+task.module)};const items=[...(task.source?[{label:'Your assessment brief / Moodle page',url:task.source}]:[]),...stepLinks,...(step?[]:[library,search,...((templates[task.type]||templates.other).flatMap(s=>s.links))]),...(task.resources||[])];return [...new Map(items.map(l=>[l.url,l])).values()];}
export function nextStep(task){if(task.status==='completed')return null;return stepsFor(task).find(s=>!s.done)||{id:'submission-check',text:'Confirm submission and mark completed',detail:'All checklist steps are done. Confirm that the assessed work was submitted or delivered and save any receipt, then mark this assignment completed.',links:[]};}
